    public void registerEvents() {
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::loadCommonForge);
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::loadServerForge);
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::loadClientForge);
        MinecraftForge.EVENT_BUS.register((Object)this);
        MinecraftForge.EVENT_BUS.register((Object)this.modMain.getCommonEvents());
