        this.onPlayerLogIn(event.getEntity());
    }

    @SubscribeEvent
    public void handlePlayerTickStart(TickEvent.PlayerTickEvent event) {
        if (event.phase == TickEvent.Phase.START) {
            super.handlePlayerTickStart(event.player);
        }
    }
}

